521			t.Fatalf("field error changed state: %+v", result)
522		}
523		if !reflect.DeepEqual(out.FinalLog, initial.Log) {
524			t.Fatalf("log changed: %+v", out.FinalLog)
525		}
526	}
527	
528	// 大索引本身不是字段非法：entries 为空时 prevLogIndex 取 MaxInt 也不要求存在
529	// 下一位置；非空请求最后条目恰好到达 MaxInt 同样合法。两者前置位置都不在本地
530	// 日志中，按原有的前缀不匹配规则拒绝，并保留较高任期更新。
531	func TestLargeRepresentableIndexesRemainLegalPrefixMismatch(t *testing.T) {
532		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1,
533			Log: []LogEntry{entry(1, 2, "a")}}
534		out := run(t, initial,
535			// 空条目心跳：不要求下一条索引存在。
536			AppendRequest{Term: 7, PrevLogIndex: math.MaxInt, PrevLogTerm: 0},
537			// 非空请求，最后一条恰好到达 MaxInt。
538			AppendRequest{Term: 8, PrevLogIndex: math.MaxInt - 1, PrevLogTerm: 0,
539				Entries: []LogEntry{entry(math.MaxInt, 8, "z")}},
540		)
541		if out.Results[0].Accepted || !strings.Contains(out.Results[0].Reason, "prev log mismatch") {
542			t.Fatalf("empty MaxInt heartbeat should be prev mismatch, got %+v", out.Results[0])
543		}
544		if out.Results[0].Term != 7 {
545			t.Fatalf("term update should survive: %d", out.Results[0].Term)
546		}
547		if out.Results[1].Accepted || !strings.Contains(out.Results[1].Reason, "prev log mismatch") {
548			t.Fatalf("last-entry-at-MaxInt request should be prev mismatch, got %+v", out.Results[1])
549		}
550		if out.Results[1].Term != 8 {
551			t.Fatalf("term update should survive: %d", out.Results[1].Term)
552		}
553		if out.FinalTerm != 8 || out.FinalCommittedIndex != 1 || len(out.FinalLog) != 1 {
554			t.Fatalf("state changed: term=%d ci=%d log=%+v", out.FinalTerm, out.FinalCommittedIndex, out.FinalLog)
555		}
556	}
557	
558	// 任何非正的真实条目索引都是字段错误：哨兵之后首条索引不能为 0 或负值，
559	// 即使它在补码意义下等于某个回绕位置。
560	func TestNonPositiveEntryIndexIsFieldError(t *testing.T) {
561		initial := InitialState{CurrentTerm: 2}
562		cases := []AppendRequest{
563			{Term: 9, PrevLogIndex: 0, Entries: []LogEntry{entry(0, 9, "x")}},
564			{Term: 9, PrevLogIndex: 0, Entries: []LogEntry{entry(-1, 9, "x")}},
565			{Term: 9, PrevLogIndex: 1, Entries: []LogEntry{entry(0, 9, "x")}},
566		}
567		for i, request := range cases {
568			out := run(t, initial, request)
569			result := out.Results[0]
570			if result.Accepted || !strings.Contains(result.Reason, "not consecutive") {
571				t.Fatalf("case %d: expected index-gap field error, got %+v", i, result)
572			}
573			if result.Term != 2 {
574				t.Fatalf("case %d: term changed to %d", i, result.Term)
575			}
576		}
577	}
578	
579	// 前置索引越过本地日志末尾：建议从末尾加一处重发，任期记 0；空日志因此是索引 1。
580	func TestConflictHintIndexBeyondLog(t *testing.T) {
581		out := run(t, InitialState{CurrentTerm: 2},
582			AppendRequest{Term: 2, PrevLogIndex: 3, PrevLogTerm: 2},
583		)
584		result := out.Results[0]
585		if result.Accepted || result.Reason != ReasonPrevLogMismatch {
586			t.Fatalf("expected prev log mismatch, got %+v", result)
587		}
588		if result.Conflict == nil || *result.Conflict != (ConflictHint{Index: 1, Term: 0}) {
589			t.Fatalf("empty log conflict = %+v, want {1 0}", result.Conflict)
590		}
591	
592		initial := InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 1, "a"), entry(2, 2, "b")}}
593		out = run(t, initial,
594			AppendRequest{Term: 2, PrevLogIndex: 5, PrevLogTerm: 2},
595		)
596		result = out.Results[0]
597		if result.Conflict == nil || *result.Conflict != (ConflictHint{Index: 3, Term: 0}) {
598			t.Fatalf("beyond-end conflict = %+v, want {3 0}", result.Conflict)
599		}
600	}
601	
602	// 前置索引存在但任期不同：反馈该位置的本地任期，以及这个任期在完整本地日志中
603	// 第一次出现的索引——即使该任期的部分条目已经提交，起点也不能推到提交位置之后。
604	func TestConflictHintTermMismatchFirstOccurrence(t *testing.T) {
605		initial := InitialState{CurrentTerm: 3, CommittedIndex: 3, Log: []LogEntry{
606			entry(1, 1, "a"), entry(2, 3, "b"), entry(3, 3, "c"), entry(4, 3, "d"),
607		}}
608		out := run(t, initial,
609			AppendRequest{Term: 3, PrevLogIndex: 4, PrevLogTerm: 2},
610		)
611		result := out.Results[0]
612		if result.Accepted || result.Reason != ReasonPrevLogMismatch {
613			t.Fatalf("expected prev log mismatch, got %+v", result)
614		}
615		if result.Conflict == nil || *result.Conflict != (ConflictHint{Index: 2, Term: 3}) {
616			t.Fatalf("conflict = %+v, want {2 3}", result.Conflict)
617		}
618		// 同任期段中间的索引同样回到段首。
619		out = run(t, initial,
620			AppendRequest{Term: 3, PrevLogIndex: 3, PrevLogTerm: 1},
621		)
622		if got := out.Results[0].Conflict; got == nil || *got != (ConflictHint{Index: 2, Term: 3}) {
623			t.Fatalf("conflict = %+v, want {2 3}", got)
624		}
625		// 冲突在首个任期段上时，起点是该段第一条。
626		out = run(t, initial,
627			AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 3},
628		)
629		if got := out.Results[0].Conflict; got == nil || *got != (ConflictHint{Index: 1, Term: 1}) {
630			t.Fatalf("conflict = %+v, want {1 1}", got)
631		}
632	}
633	
634	// 索引 0 是日志起点哨兵：携带非零前置任期按现有规则拒绝，反馈 index 1、term 0。
635	func TestConflictHintSentinelNonZeroTerm(t *testing.T) {
636		out := run(t, InitialState{CurrentTerm: 3},
637			AppendRequest{Term: 3, PrevLogIndex: 0, PrevLogTerm: 1},
638		)
639		if got := out.Results[0].Conflict; got == nil || *got != (ConflictHint{Index: 1, Term: 0}) {
640			t.Fatalf("empty log sentinel conflict = %+v, want {1 0}", got)
641		}
642		initial := InitialState{CurrentTerm: 3, Log: []LogEntry{entry(1, 2, "a"), entry(2, 2, "b")}}
643		out = run(t, initial,
644			AppendRequest{Term: 3, PrevLogIndex: 0, PrevLogTerm: 2},
645		)
646		if got := out.Results[0].Conflict; got == nil || *got != (ConflictHint{Index: 1, Term: 0}) {
647			t.Fatalf("sentinel conflict = %+v, want {1 0}", got)
648		}
649	}
650	
651	// 成功请求与其他原因的拒绝（低任期、字段非法、同任期命令冲突、覆盖已提交
652	// 条目）都不携带 conflict；多种问题并存时沿用现有拒绝顺序，只有实际因前置
653	// 日志不匹配而拒绝的结果附带反馈。
654	func TestConflictHintOnlyOnPrevLogMismatch(t *testing.T) {
655		initial := InitialState{CurrentTerm: 3, CommittedIndex: 1, Log: []LogEntry{
656			entry(1, 2, "a"), entry(2, 2, "b"),
657		}}
658		out := run(t, initial,
659			// 成功。
660			AppendRequest{Term: 3, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 2},
661			// 低任期（同时前置索引也越界，但拒绝原因是低任期）。
662			AppendRequest{Term: 2, PrevLogIndex: 9, PrevLogTerm: 9},
663			// 字段非法（同时前置索引越界）。
664			AppendRequest{Term: -1, PrevLogIndex: 9, PrevLogTerm: 0},
665			// 同任期命令冲突。
666			AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 2,
667				Entries: []LogEntry{entry(2, 2, "changed")}},
668			// 覆盖已提交条目。
669			AppendRequest{Term: 3, PrevLogIndex: 0, PrevLogTerm: 0,
670				Entries: []LogEntry{entry(1, 3, "new")}},
671		)
672		for i, result := range out.Results {
673			if result.Conflict != nil {
674				t.Fatalf("result %d (%s) should not carry conflict, got %+v", i, result.Reason, result.Conflict)
675			}
676		}
677		if !out.Results[0].Accepted {
678			t.Fatalf("first request should be accepted, got %+v", out.Results[0])
679		}
680		// 同时携带更高任期与前置不匹配：实际拒绝原因是前置不匹配，附带反馈，
681		// 且任期更新保留。
682		out = run(t, InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 2, "a")}},
683			AppendRequest{Term: 7, PrevLogIndex: 1, PrevLogTerm: 3},
684		)
685		result := out.Results[0]
686		if result.Accepted || result.Reason != ReasonPrevLogMismatch {
687			t.Fatalf("expected prev log mismatch, got %+v", result)
688		}
689		if result.Term != 7 {
690			t.Fatalf("term update should survive, got %d", result.Term)
691		}
692		if result.Conflict == nil || *result.Conflict != (ConflictHint{Index: 1, Term: 2}) {
693			t.Fatalf("conflict = %+v, want {1 2}", result.Conflict)
694		}
695	}
696	
697	// 每条反馈反映各自请求处理时的本地日志，不能借用最终日志生成。
698	func TestConflictHintReflectsLogAtRequestTime(t *testing.T) {
699		out := run(t, InitialState{CurrentTerm: 1},
700			// 先复制两条任期 1 的条目。
701			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0,
702				Entries: []LogEntry{entry(1, 1, "a"), entry(2, 1, "b")}},
703			// 此时本地日志有两条：越界反馈末尾加一。
704			AppendRequest{Term: 1, PrevLogIndex: 4, PrevLogTerm: 1},
705			// 再追加一条任期 2 的条目。
706			AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 1,
707				Entries: []LogEntry{entry(3, 2, "c")}},
708			// 此时本地日志有三条：同样的越界请求反馈随之变化。
709			AppendRequest{Term: 2, PrevLogIndex: 4, PrevLogTerm: 1},
710		)
711		if got := out.Results[1].Conflict; got == nil || *got != (ConflictHint{Index: 3, Term: 0}) {
712			t.Fatalf("second result conflict = %+v, want {3 0}", got)
713		}
714		if got := out.Results[3].Conflict; got == nil || *got != (ConflictHint{Index: 4, Term: 0}) {
715			t.Fatalf("fourth result conflict = %+v, want {4 0}", got)
716		}
717	}
718	
719	// conflict 只在前置日志不匹配的结果里出现在 JSON 中，其余结果不输出该键。
720	func TestConflictHintJSONShape(t *testing.T) {
721		out := run(t, InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 2, "a")}},
722			AppendRequest{Term: 2, PrevLogIndex: 1, PrevLogTerm: 2},
723			AppendRequest{Term: 2, PrevLogIndex: 3, PrevLogTerm: 2},
724		)
725		encoded, err := json.Marshal(out.Results[0])
726		if err != nil {
727			t.Fatal(err)
728		}
729		if strings.Contains(string(encoded), "conflict") {
730			t.Fatalf("accepted result should omit conflict, got %s", encoded)
731		}
732		encoded, err = json.Marshal(out.Results[1])
733		if err != nil {
734			t.Fatal(err)
735		}
736		var decoded map[string]any
737		if err := json.Unmarshal(encoded, &decoded); err != nil {
738			t.Fatal(err)
739		}
740		conflict, ok := decoded["conflict"].(map[string]any)
741		if !ok {
742			t.Fatalf("mismatch result should carry conflict object, got %s", encoded)
743		}
744		if conflict["index"] != float64(2) || conflict["term"] != float64(0) {
745			t.Fatalf("conflict = %v, want index 2 term 0", conflict)
746		}
747		// 编解码往返后反馈保持原样。
748		var roundTrip AppendResult
749		if err := json.Unmarshal(encoded, &roundTrip); err != nil {
750			t.Fatal(err)
751		}
752		if roundTrip.Conflict == nil || *roundTrip.Conflict != (ConflictHint{Index: 2, Term: 0}) {
753			t.Fatalf("round trip conflict = %+v, want {2 0}", roundTrip.Conflict)
754		}
755	}
