1	package mevwatch
2	
3	import (
4		"encoding/json"
5		"math"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	func runKV(t *testing.T, initial InitialState, requests ...AppendRequest) ReplicateOutput {
12		t.Helper()
13		out, err := ReplicateWithOptions(initial, requests, ReplicateOptions{ApplyKV: true})
14		if err != nil {
15			t.Fatalf("ReplicateWithOptions returned error: %v", err)
16		}
17		return out
18	}
19	
20	func appliedIndexOf(t *testing.T, result AppendResult) int {
21		t.Helper()
22		if result.AppliedIndex == nil {
23			t.Fatalf("appliedIndex missing in %+v", result)
24		}
25		return *result.AppliedIndex
26	}
27	
28	func finalKVOf(t *testing.T, out ReplicateOutput) map[string]string {
29		t.Helper()
30		if out.FinalAppliedIndex == nil || out.FinalKV == nil {
31			t.Fatalf("final apply fields missing in %+v", out)
32		}
33		return out.FinalKV
34	}
35	
36	func TestKVParseCommands(t *testing.T) {
37		cases := []struct {
38			command    string
39			wantOp     kvOperation
40			wantReason string
41		}{
42			{"set x=1", kvOperation{key: "x", value: "1"}, ""},
43			{"set x=", kvOperation{key: "x", value: ""}, ""},           // 空值
44			{"set k=a b c", kvOperation{key: "k", value: "a b c"}, ""}, // 值含空格
45			{"set k=a=b=c", kvOperation{key: "k", value: "a=b=c"}, ""}, // 值含额外等号
46			{"set k=你好 世界", kvOperation{key: "k", value: "你好 世界"}, ""}, // 中文值
47			{"set k=1 ", kvOperation{key: "k", value: "1 "}, ""},       // 尾部空白保留在值里
48			{"delete x", kvOperation{isDelete: true, key: "x"}, ""},
49			{"delete 键", kvOperation{isDelete: true, key: "键"}, ""},
50			{"set", kvOperation{}, ApplyReasonUnknownCommand}, // 没有空格与键
51			{"delete", kvOperation{}, ApplyReasonUnknownCommand},
52			{"set x", kvOperation{}, ApplyReasonSetMissingEquals},     // 缺等号
53			{"set =1", kvOperation{}, ApplyReasonEmptyKey},            // 空键
54			{"set  x=1", kvOperation{}, ApplyReasonKeyHasWhitespace},  // 两个空格：键以空格开头
55			{"set x y=1", kvOperation{}, ApplyReasonKeyHasWhitespace}, // 键含空白
56			{"set\tx=1", kvOperation{}, ApplyReasonUnknownCommand},    // 制表符不是普通空格
57			{"delete x y", kvOperation{}, ApplyReasonKeyHasWhitespace},
58			{"delete x ", kvOperation{}, ApplyReasonKeyHasWhitespace}, // 尾部空白不裁剪
59			{"delete a=b", kvOperation{}, ApplyReasonKeyHasEquals},    // 键含等号
60			{" set x=1", kvOperation{}, ApplyReasonUnknownCommand},    // 前导空白不裁剪
61			{"SET x=1", kvOperation{}, ApplyReasonUnknownCommand},     // 区分大小写
62			{"get x", kvOperation{}, ApplyReasonUnknownCommand},
63			{"", kvOperation{}, ApplyReasonUnknownCommand},
64		}
65		for _, tc := range cases {
66			op, reason := parseKVCommand(tc.command)
67			if reason != tc.wantReason {
68				t.Fatalf("parseKVCommand(%q) reason = %q, want %q", tc.command, reason, tc.wantReason)
69			}
70			if tc.wantReason == "" && op != tc.wantOp {
71				t.Fatalf("parseKVCommand(%q) = %+v, want %+v", tc.command, op, tc.wantOp)
72			}
73		}
74	}
75	
76	func TestKVInitialCommittedPrefixWithoutRequests(t *testing.T) {
77		initial := InitialState{CurrentTerm: 2, CommittedIndex: 2, Log: []LogEntry{
78			entry(1, 1, "set x=1"), entry(2, 2, "set y=你好"), entry(3, 2, "set z=9"),
79		}}
80		out := runKV(t, initial)
81		kv := finalKVOf(t, out)
82		want := map[string]string{"x": "1", "y": "你好"}
83		if !reflect.DeepEqual(kv, want) {
84			t.Fatalf("finalKV = %v, want %v", kv, want)
85		}
86		if *out.FinalAppliedIndex != 2 {
87			t.Fatalf("finalAppliedIndex = %d, want 2", *out.FinalAppliedIndex)
88		}
89		if out.FinalApplyError != nil {
90			t.Fatalf("unexpected apply error: %+v", out.FinalApplyError)
91		}
92		if len(out.Results) != 0 {
93			t.Fatalf("unexpected results: %+v", out.Results)
94		}
95	}
96	
97	func TestKVAppliesOnlyNewlyCommitted(t *testing.T) {
98		out := runKV(t, InitialState{CurrentTerm: 1},
99			// 追加三条但一条都不提交：不应用。
100			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 0,
101				Entries: []LogEntry{entry(1, 1, "set a=1"), entry(2, 1, "set b=2"), entry(3, 1, "delete a")}},
102			// 心跳推进提交到 2：应用前两条。
103			AppendRequest{Term: 1, PrevLogIndex: 3, PrevLogTerm: 1, LeaderCommit: 2},
104			// 重复的心跳：提交位置不变，不重复应用。
105			AppendRequest{Term: 1, PrevLogIndex: 3, PrevLogTerm: 1, LeaderCommit: 2},
106			// 提交最后一条 delete。
107			AppendRequest{Term: 1, PrevLogIndex: 3, PrevLogTerm: 1, LeaderCommit: 3},
108		)
109		wantApplied := []int{0, 2, 2, 3}
110		for i, result := range out.Results {
111			if !result.Accepted {
112				t.Fatalf("result %d rejected: %s", i, result.Reason)
113			}
114			if got := appliedIndexOf(t, result); got != wantApplied[i] {
115				t.Fatalf("result %d appliedIndex = %d, want %d", i, got, wantApplied[i])
116			}
117			if result.ApplyError != nil {
118				t.Fatalf("result %d unexpected apply error: %+v", i, result.ApplyError)
119			}
120		}
121		// 同一个键的多次操作按日志次序生效：set a=1 之后 delete a。
122		kv := finalKVOf(t, out)
123		want := map[string]string{"b": "2"}
124		if !reflect.DeepEqual(kv, want) {
125			t.Fatalf("finalKV = %v, want %v", kv, want)
126		}
127		if *out.FinalAppliedIndex != 3 {
128			t.Fatalf("finalAppliedIndex = %d, want 3", *out.FinalAppliedIndex)
129		}
130	}
131	
132	func TestKVDeleteMissingKeySucceeds(t *testing.T) {
133		out := runKV(t, InitialState{CurrentTerm: 1},
134			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 1,
135				Entries: []LogEntry{entry(1, 1, "delete ghost")}},
136		)
137		if !out.Results[0].Accepted || out.Results[0].ApplyError != nil {
138			t.Fatalf("deleting a missing key should succeed: %+v", out.Results[0])
139		}
140		if got := appliedIndexOf(t, out.Results[0]); got != 1 {
141			t.Fatalf("appliedIndex = %d, want 1", got)
142		}
143		if kv := finalKVOf(t, out); len(kv) != 0 {
144			t.Fatalf("finalKV = %v, want empty", kv)
145		}
146	}
147	
148	func TestKVFormatErrorStopsApplication(t *testing.T) {
149		initial := InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
150			entry(1, 1, "set ok=1"),
151		}}
152		out := runKV(t, initial,
153			// 追加 idx2（格式错误）与 idx3，并提交到 3：应用停在 idx1。
154			AppendRequest{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
155				Entries: []LogEntry{entry(2, 1, "set bad"), entry(3, 1, "set later=3")}},
156			// 复制与提交仍可继续推进，但应用状态保持停住。
157			AppendRequest{Term: 2, PrevLogIndex: 3, PrevLogTerm: 1, LeaderCommit: 4,
158				Entries: []LogEntry{entry(4, 2, "set more=4")}},
159		)
160		if !out.Results[0].Accepted || !out.Results[1].Accepted {
161			t.Fatalf("replication should still be accepted: %+v", out.Results)
162		}
163		for i, result := range out.Results {
164			if got := appliedIndexOf(t, result); got != 1 {
165				t.Fatalf("result %d appliedIndex = %d, want 1 (stuck)", i, got)
166			}
167			if result.ApplyError == nil || result.ApplyError.Index != 2 ||
168				result.ApplyError.Reason != ApplyReasonSetMissingEquals {
169				t.Fatalf("result %d applyError = %+v, want index 2 missing '='", i, result.ApplyError)
170			}
171		}
172		// 日志、任期与提交位置继续变化。
173		if out.FinalTerm != 2 || out.FinalCommittedIndex != 4 || len(out.FinalLog) != 4 {
174			t.Fatalf("replication state should advance: term=%d ci=%d log=%+v",
175				out.FinalTerm, out.FinalCommittedIndex, out.FinalLog)
176		}
177		// 应用状态停住：idx2 及之后（包括格式正确的 idx3/idx4）都不执行。
178		if *out.FinalAppliedIndex != 1 {
179			t.Fatalf("finalAppliedIndex = %d, want 1", *out.FinalAppliedIndex)
180		}
181		kv := finalKVOf(t, out)
182		want := map[string]string{"ok": "1"}
183		if !reflect.DeepEqual(kv, want) {
184			t.Fatalf("finalKV = %v, want %v", kv, want)
185		}
186		if out.FinalApplyError == nil || out.FinalApplyError.Index != 2 {
187			t.Fatalf("finalApplyError = %+v, want index 2", out.FinalApplyError)
188		}
189	}
190	
191	func TestKVErrorInInitialCommittedPrefix(t *testing.T) {
192		initial := InitialState{CurrentTerm: 1, CommittedIndex: 3, Log: []LogEntry{
193			entry(1, 1, "set a=1"), entry(2, 1, "bogus"), entry(3, 1, "set b=2"),
194		}}
195		out := runKV(t, initial)
196		if *out.FinalAppliedIndex != 1 {
197			t.Fatalf("finalAppliedIndex = %d, want 1", *out.FinalAppliedIndex)
198		}
199		kv := finalKVOf(t, out)
200		if !reflect.DeepEqual(kv, map[string]string{"a": "1"}) {
201			t.Fatalf("finalKV = %v, want only first entry applied", kv)
