743	// TestKVRoundTripLegacyResultWithoutApplyFields 完全没有应用字段的旧结果保持
744	// 原有输出形状；接受状态、拒绝原因、任期、提交位置与日志内容原样保留。
745	func TestKVRoundTripLegacyResultWithoutApplyFields(t *testing.T) {
746		data := []byte(`{"results":[{"accepted":false,` +
747			`"reason":"stale term: leader term is lower than current term",` +
748			`"term":5,"committedIndex":1}],` +
749			`"finalTerm":5,"finalCommittedIndex":1,` +
750			`"finalLog":[{"index":1,"term":5,"command":"a"}]}`)
751		var out ReplicateOutput
752		if err := json.Unmarshal(data, &out); err != nil {
753			t.Fatal(err)
754		}
755		reencoded, err := json.Marshal(out)
756		if err != nil {
757			t.Fatal(err)
758		}
759		want := decodeMap(t, data)
760		got := decodeMap(t, reencoded)
761		if !reflect.DeepEqual(got, want) {
762			t.Fatalf("legacy result changed shape:\nwant %v\n got %v", want, got)
763		}
764		results := resultMaps(t, got)
765		mustLackKeys(t, results[0], "legacy request", "appliedIndex", "applyError")
766		mustLackKeys(t, got, "legacy final output",
767			"finalAppliedIndex", "finalKV", "finalApplyError")
