911	// partialConfirmationInitial 是“部分确认不提交尾部”回归测试的初始状态：任期 2，
912	// 日志索引 1..4 的任期均为 2，只有 idx1（set balance=100）已提交；idx2 把
913	// balance 改成 200，idx3 是缺少等号的 set 命令，idx4 删除 balance——后三条都是
914	// 未提交尾部，idx3 的格式错误不能在提交之前暴露。
915	func partialConfirmationInitial() InitialState {
916		return InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
917			entry(1, 2, "set balance=100"),
918			entry(2, 2, "set balance=200"),
919			entry(3, 2, "set balance"), // 缺少 '='：提交到此处时才报告
920			entry(4, 2, "delete balance"),
921		}}
922	}
