924	// TestKVPartialConfirmationKeepsTailUncommitted 回归保障：合法请求只确认部分日志时，
925	// 本地保留的更长未提交尾部不能因此被提交或应用。日志仍然存在、日志已经提交、命令
926	// 已经应用是三种不同的结果，必须分别从每一步的答复与最终状态中看出：
927	//   - 初始只提交 idx1：键值表只有 balance=100，idx3 的格式错误不出现；
928	//   - 请求一（任期 2、前置 idx1、只携带与本地 idx2 相同的条目、leaderCommit=4）
929	//     成功且答复原因为 ok：四条日志全部保留，但提交与应用只到 2，balance=200，
930	//     无应用错误；
931	//   - 请求二（前置 idx2、空条目、leaderCommit=4）同样成功：确认位置仍是 2，尾部
932	//     的 delete 不执行，idx3 的格式错误也不暴露；
933	//   - 请求三（前置 idx4、leaderCommit=4）才把提交推进到 4：idx3 的错误被报告，
934	//     应用停在 2，idx4 的删除不生效，balance 仍为 200；复制仍成功、日志不变；
935	//   - 请求四（前置 idx2、leaderCommit=1）确认位置与领导者提交位置都低于已提交
936	//     索引：提交、应用与已报告的错误都不得倒退。
937	func TestKVPartialConfirmationKeepsTailUncommitted(t *testing.T) {
938		initial := partialConfirmationInitial()
939		fullLog := append([]LogEntry(nil), initial.Log...)
940	
941		// 没有请求时：只应用初始已提交前缀，尾部三条不产生任何效果。
942		start := runKV(t, initial)
943		if *start.FinalAppliedIndex != 1 {
944			t.Fatalf("initial appliedIndex = %d, want 1", *start.FinalAppliedIndex)
945		}
946		if !reflect.DeepEqual(finalKVOf(t, start), map[string]string{"balance": "100"}) {
947			t.Fatalf("initial kv = %v, want only balance=100", start.FinalKV)
948		}
949		if start.FinalApplyError != nil {
950			t.Fatalf("uncommitted bad entry reported early: %+v", start.FinalApplyError)
951		}
952	
953		// 请求一：只确认到 idx2，领导者却声明已提交到 4。
954		partial := AppendRequest{Term: 2, PrevLogIndex: 1, PrevLogTerm: 2, LeaderCommit: 4,
955			Entries: []LogEntry{entry(2, 2, "set balance=200")}}
956		// 请求二：空条目心跳，前置仍为 idx2，领导者提交位置仍为 4。
957		heartbeat := AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 4}
958		// 请求三：前置确认到 idx4，提交位置才推进到 4。
959		confirmAll := AppendRequest{Term: 2, PrevLogIndex: 4, PrevLogTerm: 2, LeaderCommit: 4}
960		// 请求四：确认位置与 leaderCommit 都低于已提交索引，不得倒退。
961		lowerCommit := AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 1}
962	
963		// 若输入停在请求一：答复成功，日志四条全在，提交与应用只到 2。
964		stopped := runKV(t, initial, partial)
965		r := stopped.Results[0]
966		if !r.Accepted || r.Reason != ReasonOK {
967			t.Fatalf("partial confirmation must stay a normal success: %+v", r)
968		}
969		if r.CommittedIndex != 2 {
970			t.Fatalf("commit advanced beyond confirmed index: %d, want 2", r.CommittedIndex)
971		}
972		if got := appliedIndexOf(t, r); got != 2 {
973			t.Fatalf("applied index = %d, want 2", got)
974		}
975		if r.ApplyError != nil {
976			t.Fatalf("uncommitted tail error reported early: %+v", r.ApplyError)
977		}
978		if !reflect.DeepEqual(stopped.FinalLog, fullLog) {
979			t.Fatalf("tail deleted by partial confirmation: %+v", stopped.FinalLog)
980		}
981		if stopped.FinalCommittedIndex != 2 || *stopped.FinalAppliedIndex != 2 {
982			t.Fatalf("final state = ci %d applied %d, want 2/2",
983				stopped.FinalCommittedIndex, *stopped.FinalAppliedIndex)
984		}
985		if !reflect.DeepEqual(finalKVOf(t, stopped), map[string]string{"balance": "200"}) {
986			t.Fatalf("kv = %v, want only balance=200 (delete must not run)", stopped.FinalKV)
987		}
988		if stopped.FinalApplyError != nil {
989			t.Fatalf("unexpected apply error: %+v", stopped.FinalApplyError)
990		}
991	
992		// 完整过程：四个请求的答复逐步区分“日志保留 / 已提交 / 已应用”。
993		out := runKV(t, initial, partial, heartbeat, confirmAll, lowerCommit)
994		if len(out.Results) != 4 {
995			t.Fatalf("got %d results, want 4", len(out.Results))
996		}
997		// 四个请求全部以正常成功原因接受：不能为了阻止尾部应用而拒绝请求。
998		for i, result := range out.Results {
999			if !result.Accepted || result.Reason != ReasonOK {
1000				t.Fatalf("result %d must be a normal success, got %+v", i, result)
1001			}
1002			if result.Term != 2 {
1003				t.Fatalf("result %d term = %d, want 2", i, result.Term)
1004			}
1005		}
1006		// 请求一、二：确认位置只有 2，leaderCommit=4 不能把提交推过 2。
1007		for i := 0; i < 2; i++ {
1008			if out.Results[i].CommittedIndex != 2 {
1009				t.Fatalf("result %d committedIndex = %d, want 2 (tail not confirmed)",
1010					i, out.Results[i].CommittedIndex)
1011			}
1012			if got := appliedIndexOf(t, out.Results[i]); got != 2 {
1013				t.Fatalf("result %d appliedIndex = %d, want 2", i, got)
1014			}
1015			if out.Results[i].ApplyError != nil {
1016				t.Fatalf("result %d exposed uncommitted tail error: %+v", i, out.Results[i].ApplyError)
1017			}
1018		}
1019		// 请求三：提交推进到 4，idx3 的格式错误此时才报告；应用停在 2。
1020		third := out.Results[2]
1021		if third.CommittedIndex != 4 {
1022			t.Fatalf("result 2 committedIndex = %d, want 4", third.CommittedIndex)
1023		}
1024		if got := appliedIndexOf(t, third); got != 2 {
1025			t.Fatalf("result 2 appliedIndex = %d, want 2 (stuck before bad entry)", got)
1026		}
1027		if third.ApplyError == nil || third.ApplyError.Index != 3 ||
1028			third.ApplyError.Reason != ApplyReasonSetMissingEquals {
1029			t.Fatalf("result 2 applyError = %+v, want index 3 missing '='", third.ApplyError)
1030		}
1031		// 请求四：确认位置与 leaderCommit 都低于已提交索引，一切不得倒退。
1032		fourth := out.Results[3]
1033		if fourth.CommittedIndex != 4 {
1034			t.Fatalf("result 3 committedIndex moved backward: %d, want 4", fourth.CommittedIndex)
1035		}
1036		if got := appliedIndexOf(t, fourth); got != 2 {
1037			t.Fatalf("result 3 appliedIndex = %d, want 2", got)
1038		}
1039		if fourth.ApplyError == nil || fourth.ApplyError.Index != 3 {
1040			t.Fatalf("result 3 applyError = %+v, want index 3 retained", fourth.ApplyError)
1041		}
1042	
1043		// 最终状态：完整日志不因应用失败而改变；提交到 4、应用停在 2、balance 仍为
1044		// 200——idx4 的删除不能生效，idx3 的错误保留在最终输出中。
1045		if !reflect.DeepEqual(out.FinalLog, fullLog) {
1046			t.Fatalf("final log = %+v, want unchanged %+v", out.FinalLog, fullLog)
1047		}
1048		if out.FinalTerm != 2 || out.FinalCommittedIndex != 4 {
1049			t.Fatalf("final state = term %d ci %d, want term 2 ci 4", out.FinalTerm, out.FinalCommittedIndex)
1050		}
1051		if *out.FinalAppliedIndex != 2 {
1052			t.Fatalf("final appliedIndex = %d, want 2", *out.FinalAppliedIndex)
1053		}
