1298			{"only uppercase nonzero apply index", `"APPLIEDINDEX":5`, 5, nil},
1299			{"only mixed-case apply error object",
1300				`"aPpLyErRoR":{"index":3,"reason":"boom"}`, 0,
1301				map[string]any{"index": float64(3), "reason": "boom"}},
