1448		// 情形二：只有请求 0 以变体名记录；最终层与请求 1 必须保持无应用字段。
1449		data2 := `{"results":[` +
1450			`{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"AppliedIndex":0,"APPLYERROR":null},` +
1451			`{"accepted":true,"reason":"ok","term":1,"committedIndex":0}` +
1452			`],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`
1453		var out2 ReplicateOutput
1454		if err := json.Unmarshal([]byte(data2), &out2); err != nil {
1455			t.Fatal(err)
1456		}
1457		reencoded2, err := json.Marshal(out2)
1458		if err != nil {
1459			t.Fatal(err)
1460		}
1461		m2 := decodeMap(t, reencoded2)
1462		results2 := resultMaps(t, m2)
1463		mustHaveKeys(t, results2[0], "applied request", perRequestKeys...)
1464		if results2[0]["appliedIndex"] != float64(0) || results2[0]["applyError"] != nil {
1465			t.Fatalf("applied request values changed: %v", results2[0])
1466		}
1467		mustLackKeys(t, results2[1], "plain request", perRequestKeys...)
1468		mustLackKeys(t, m2, "final output", finalKeys...)
1469	}
