1471	// TestKVRoundTripSimilarKeysDoNotTrigger 与应用字段名相似但大小写折叠后仍不
1472	// 相同的无关键，不能触发应用字段补齐；输出形状与完全没有应用字段的旧结果一致。
1473	func TestKVRoundTripSimilarKeysDoNotTrigger(t *testing.T) {
1474		perRequestSimilar := []string{
1475			`"myAppliedIndex":9`,
1476			`"appliedIndex2":9`,
1477			`"applied_index":9`,
1478			`"ApplyErrors":null`,
1479			`"xapplyError":null`,
1480		}
1481		for _, extra := range perRequestSimilar {
1482			data := `{"accepted":true,"reason":"ok","term":1,"committedIndex":0,` + extra + `}`
1483			var result AppendResult
1484			if err := json.Unmarshal([]byte(data), &result); err != nil {
1485				t.Fatalf("decode %s: %v", data, err)
1486			}
1487			reencoded, err := json.Marshal(result)
1488			if err != nil {
1489				t.Fatal(err)
1490			}
1491			m := decodeMap(t, reencoded)
1492			mustLackKeys(t, m, "result with "+extra, "appliedIndex", "applyError")
1493			if result.applyFields {
1494				t.Fatalf("similar key %q must not open apply fields switch", extra)
1495			}
1496		}
1497	
1498		finalSimilar := []string{
1499			`"finalAppliedIndexV2":9`,
1500			`"finalKVVersion":{}`,
1501			`"finalApplyErrorCode":null`,
1502			`"FinalAppliedIndex2":1`,
1503			`"FINAL_KV":{}`,
1504		}
1505		for _, extra := range finalSimilar {
1506			data := `{"results":[],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[],` + extra + `}`
1507			var out ReplicateOutput
1508			if err := json.Unmarshal([]byte(data), &out); err != nil {
1509				t.Fatalf("decode %s: %v", data, err)
1510			}
1511			reencoded, err := json.Marshal(out)
1512			if err != nil {
1513				t.Fatal(err)
1514			}
1515			m := decodeMap(t, reencoded)
1516			mustLackKeys(t, m, "output with "+extra,
1517				"finalAppliedIndex", "finalKV", "finalApplyError")
1518			if out.applyFields {
1519				t.Fatalf("similar key %q must not open apply fields switch", extra)
1520			}
1521		}
1522	}
1523	
1524	// TestKVRoundTripCaseFoldedBadTypesRejected 应用索引写成字符串、键值表写成数组
1525	// 等现有非法类型，即使字段名换了大小写也要返回解码错误。
1526	func TestKVRoundTripCaseFoldedBadTypesRejected(t *testing.T) {
1527		badInputs := []string{
1528			`{"results":[],"finalTerm":0,"finalCommittedIndex":0,"finalLog":[],"FINALAPPLIEDINDEX":"0"}`,
1529			`{"results":[],"finalTerm":0,"finalCommittedIndex":0,"finalLog":[],"FinalKV":[]}`,
1530			`{"results":[],"finalTerm":0,"finalCommittedIndex":0,"finalLog":[],"FINALAPPLYERROR":{"index":"2","reason":"x"}}`,
1531			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"APPLIEDINDEX":"0"}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
1532			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"ApplyError":{"index":"2","reason":"x"}}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
1533		}
1534		for _, data := range badInputs {
1535			var out ReplicateOutput
1536			if err := json.Unmarshal([]byte(data), &out); err == nil {
