1542	// TestKVRoundTripCaseFoldedFailedReuseKeepsPreviousResult 复用已有结果对象读入
1543	// 大小写变体字段名的非法 JSON 时必须报错，并完整保留读入前的结果（含其应用
1544	// 状态）；之后输出不能混入这次读入的任何内容，也不能被变体名打开开关。
1545	func TestKVRoundTripCaseFoldedFailedReuseKeepsPreviousResult(t *testing.T) {
1546		original := runKV(t, InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
1547			entry(1, 1, "set x=1"),
1548		}},
1549			AppendRequest{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
1550				Entries: []LogEntry{entry(2, 1, "set bad"), entry(3, 1, "set k=v")}},
1551		)
1552		originalJSON, err := json.Marshal(original)
1553		if err != nil {
1554			t.Fatal(err)
1555		}
1556		badInputs := []string{
1557			// 错误位于某条请求答复内，字段名大写。
1558			`{"results":[{"accepted":true,"reason":"ok","term":9,"committedIndex":9,"APPLIEDINDEX":"3"}],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[]}`,
1559			// 最终层：应用索引写成字符串，字段名首字母大写。
1560			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FinalAppliedIndex":"9"}`,
1561			// 最终层：键值表写成数组，字段名全大写。
1562			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FINALKV":["nope"]}`,
1563		}
1564		for _, bad := range badInputs {
1565			var out ReplicateOutput
1566			if err := json.Unmarshal(originalJSON, &out); err != nil {
1567				t.Fatal(err)
1568			}
1569			if err := json.Unmarshal([]byte(bad), &out); err == nil {
1570				t.Fatalf("expected decode error for %s", bad)
1571			}
1572			reencoded, err := json.Marshal(out)
1573			if err != nil {
1574				t.Fatal(err)
1575			}
1576			if string(reencoded) != string(originalJSON) {
1577				t.Fatalf("previous result not preserved after failed decode of %s:\nwant %s\n got %s",
1578					bad, originalJSON, reencoded)
1579			}
1580		}
