1582	
1583	// TestKVRoundTripCaseFoldedSuccessfulReuseNoResidue 复用结果对象成功读入下一份
1584	// JSON 时只保留本次内容：先读入以变体名记录应用状态的结果，再读入完全没有
1585	// 应用字段的旧结果，后一次输出不得残留前一次的键值表、错误或应用位置；反方向
1586	// （先旧后变体）则必须按本次内容补齐完整应用字段。
1587	func TestKVRoundTripCaseFoldedSuccessfulReuseNoResidue(t *testing.T) {
1588		variantApplied := `{"results":[{"accepted":true,"reason":"ok","term":1,` +
1589			`"committedIndex":1,"AppliedIndex":1,"ApplyError":null}],` +
1590			`"finalTerm":1,"finalCommittedIndex":1,` +
1591			`"finalLog":[{"index":1,"term":1,"command":"set x=1"}],` +
1592			`"FinalAppliedIndex":1,"FinalKV":{"x":"1"},"FINALAPPLYERROR":null}`
1593		plain := `{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":1}],` +
1594			`"finalTerm":1,"finalCommittedIndex":1,` +
1595			`"finalLog":[{"index":1,"term":1,"command":"set x=1"}]}`
1596	
1597		// 先变体后旧结果：无残留。
1598		var out ReplicateOutput
1599		if err := json.Unmarshal([]byte(variantApplied), &out); err != nil {
1600			t.Fatal(err)
1601		}
1602		if err := json.Unmarshal([]byte(plain), &out); err != nil {
1603			t.Fatal(err)
1604		}
1605		body, err := json.Marshal(out)
1606		if err != nil {
1607			t.Fatal(err)
1608		}
1609		for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
1610			if strings.Contains(string(body), field) {
1611				t.Fatalf("stale apply field %q after reusing object: %s", field, body)
1612			}
1613		}
1614		if out.FinalKV != nil || out.FinalAppliedIndex != nil || out.FinalApplyError != nil {
1615			t.Fatalf("stale apply state in %+v", out)
1616		}
1617	
1618		// 先旧结果后变体：按本次内容带齐标准字段。
1619		var out2 ReplicateOutput
1620		if err := json.Unmarshal([]byte(plain), &out2); err != nil {
1621			t.Fatal(err)
1622		}
1623		if err := json.Unmarshal([]byte(variantApplied), &out2); err != nil {
1624			t.Fatal(err)
1625		}
1626		body2, err := json.Marshal(out2)
1627		if err != nil {
1628			t.Fatal(err)
1629		}
1630		m := decodeMap(t, body2)
1631		mustHaveKeys(t, m, "final output",
1632			"finalAppliedIndex", "finalKV", "finalApplyError")
1633		if m["finalAppliedIndex"] != float64(1) ||
1634			!reflect.DeepEqual(m["finalKV"], map[string]any{"x": "1"}) ||
1635			m["finalApplyError"] != nil {
1636			t.Fatalf("variant-keyed apply state not restored after reuse: %v", m)
1637		}
1638		results := resultMaps(t, m)
1639		mustHaveKeys(t, results[0], "applied request", "appliedIndex", "applyError")
1640	}
